import Foundation

public enum ClipHistory {
    public static let limit = 300

    static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    public static func shouldRecord(types: [String]) -> Bool {
        privateTypes.isDisjoint(with: types)
    }

    public static func adding(_ entry: ClipEntry, to entries: [ClipEntry]) -> [ClipEntry] {
        guard !entry.text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return entries }
        let others = entries.filter { $0.text != entry.text }
        return Array(([entry] + others).prefix(limit))
    }

    public static func results(for query: String, in entries: [ClipEntry], now: Date) -> [ResultItem] {
        let query = query.trimmingCharacters(in: .whitespaces)
        let matching = query.isEmpty ? entries : entries.filter { $0.text.localizedCaseInsensitiveContains(query) }
        return matching.map { ResultItem.clip($0, now: now) }
    }

    public static func age(of date: Date, now: Date) -> String {
        let seconds = max(0, Int(now.timeIntervalSince(date)))
        switch seconds {
        case ..<60: return "Just now"
        case ..<3600: return "\(seconds / 60) min ago"
        case ..<86_400: return "\(seconds / 3600) h ago"
        default:
            let days = seconds / 86_400
            return days == 1 ? "Yesterday" : "\(days) days ago"
        }
    }

    public static func title(of text: String) -> String {
        text.split(whereSeparator: \.isNewline).first.map { $0.trimmingCharacters(in: .whitespaces) } ?? text
    }
}
